// === Lecture brute des entités HA (climatisation / chauffage gratuits) ===
// Getters uniquement, pas de logique métier. Les unités sont décrites par une
// liste ORDONNÉE (priorité décroissante) dans CLIM_UNITS : la première servie
// est la première de la liste.
// La température de chaque pièce provient de l'attribut `current_temperature`
// de l'unité elle-même, aucune sonde externe nécessaire.
// PREREQUIS : cocher "Enable global context store" sur le nœud serveur HA.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

let g;
try {
    g = global.get('homeassistant').homeAssistant.states;
    if (!g) throw new Error('states indisponibles');
} catch (e) {
    node.warn('HA indisponible, tick ignoré : ' + e.message);
    return null;
}

const eStr = (k, def) => {
    const v = env.get(k);
    return (v === undefined || v === null || v === '') ? def : String(v);
};
const eNum = (k, def) => {
    const v = parseFloat(env.get(k));
    return isNaN(v) ? def : v;
};
const n = (id, def = 0) => {
    const v = parseFloat(g[id]?.state);
    return isNaN(v) ? def : v;
};
const numOrNull = (id) => {
    const raw = g[id]?.state;
    if (raw === undefined || raw === 'unavailable' || raw === 'unknown') return null;
    const v = parseFloat(raw);
    return isNaN(v) ? null : v;
};
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const list = (s) => s.split(',').map(x => x.trim()).filter(x => x.length > 0);

// --- Constantes du modèle ---
msg.climLoadW = clamp(eNum('CLIM_LOAD_W', 800), 100, 10000);
msg.cumulusLoadW = clamp(eNum('CUMULUS_LOAD_W', 1200), 100, 10000);
msg.minRunMs = clamp(eNum('CLIM_MIN_RUN_MIN', 20), 0, 240) * 60000;
msg.minOffMs = clamp(eNum('CLIM_MIN_OFF_MIN', 15), 0, 240) * 60000;
msg.hystMs = clamp(eNum('CLIM_HYST_MIN', 5), 1, 60) * 60000;
msg.stopRatio = clamp(eNum('CLIM_STOP_RATIO', 0.75), 0, 1);
msg.storeBand = clamp(eNum('CLIM_STORE_BAND', 1.5), 0, 6);
msg.coolFloor = eNum('CLIM_COOL_FLOOR', 21);
msg.heatCeiling = eNum('CLIM_HEAT_CEILING', 23);
msg.outdoorCoolMin = eNum('CLIM_OUTDOOR_COOL_MIN', 24);
msg.outdoorHeatMax = eNum('CLIM_OUTDOOR_HEAT_MAX', 17);
msg.maxUnits = Math.round(clamp(eNum('CLIM_MAX_UNITS', 5), 1, 20));
// L'eau chaude garde la priorité sur le confort jusqu'à cette température.
msg.priorityTempSetting = clamp(eNum('HOT_WATER_PRIORITY_TEMP', 60), 30, 70);
// Veille d'un disjoncteur intelligent, unités à l'arrêt. Retirée de la mesure
// de groupe : éteindre les unités ne la rend pas, elle n'est pas récupérable.
msg.groupStandbyW = clamp(eNum('CLIM_GROUP_STANDBY_W', 5), 0, 200);

// --- Entités ---
const outdoorId = eStr('CLIM_OUTDOOR_SENSOR', '');
const solarId = eStr('SOLAR_SENSOR', 'sensor.powermeter_power_a');
const gridId = eStr('GRID_SENSOR', 'sensor.powermeter_power_b');
msg.cumulusSensor = eStr('CUMULUS_SENSOR', 'sensor.cumulus_automation');

// --- Paramètres utilisateur (helpers HA) ---
msg.enabled = g['input_boolean.clim_automation_enabled']?.state === 'on';
msg.targetCool = clamp(n('input_number.clim_target_cool', 25), 18, 32);
msg.targetHeat = clamp(n('input_number.clim_target_heat', 20), 12, 26);

// Surplus requis PAR UNITÉ. Défaut : puissance d'une unité, donc aucun watt
// pris au réseau. Helper absent ou à 0 → défaut.
const trigRaw = numOrNull('input_number.clim_surplus_trigger');
msg.surplusTrigPerUnit = (trigRaw != null && trigRaw > 0)
    ? Math.round(trigRaw) : Math.round(msg.climLoadW);

const SEASON_MAP = {
    auto: 'auto', froid: 'froid', chaud: 'chaud', 'arrêt': 'arret', arret: 'arret',
    cool: 'froid', heat: 'chaud', off: 'arret'
};
const seasonRaw = String(g['input_select.clim_season_mode']?.state || 'auto').toLowerCase();
msg.seasonMode = SEASON_MAP[seasonRaw] || 'auto';

// --- Sonde extérieure (optionnelle) ---
msg.outdoorTemp = outdoorId ? numOrNull(outdoorId) : null;
msg.outdoorAvailable = msg.outdoorTemp != null;

// --- Mesures électriques ---
msg.solar = n(solarId, 0);
msg.gridPower = n(gridId, 0);   // > 0 import réseau, < 0 injection
msg.surplus = -msg.gridPower;

// --- Groupes de disjoncteurs intelligents ---
// Chaque groupe apporte deux choses que l'estimation ne donne pas : la
// consommation RÉELLE de ses unités, et l'état de son alimentation. Format JSON,
// une entrée par disjoncteur. Absent ou illisible : repli sur l'estimation
// CLIM_LOAD_W par unité, comportement d'origine.
let groupsRaw = env.get('CLIM_GROUPS');
let groupDefs = [];
try {
    if (Array.isArray(groupsRaw)) groupDefs = groupsRaw;
    else if (typeof groupsRaw === 'string' && groupsRaw.trim()) groupDefs = JSON.parse(groupsRaw);
} catch (e) {
    node.warn('CLIM_GROUPS illisible (JSON invalide), mesure par groupe désactivée : '
        + e.message);
    groupDefs = [];
}

msg.groups = groupDefs.map(gr => {
    const swState = gr.switch ? g[gr.switch]?.state : undefined;
    return {
        name: gr.name || gr.switch || '?',
        switchId: gr.switch || null,
        // État inconnu (pas de disjoncteur déclaré) : supposé alimenté, sinon
        // une lecture manquante suffirait à geler tout le groupe.
        breakerOn: (swState === 'on' || swState === 'off') ? swState === 'on' : true,
        breakerKnown: swState === 'on' || swState === 'off',
        powerSensor: gr.power || null,
        power: gr.power ? numOrNull(gr.power) : null,
        units: Array.isArray(gr.units) ? gr.units : []
    };
});

const groupOf = {};
for (const gr of msg.groups) {
    for (const uid of gr.units) groupOf[uid] = gr;
}

// --- Unités climatisation, par ordre de priorité ---
const ids = list(eStr('CLIM_UNITS',
    'climate.salon_room_temperature,climate.daikinap21104_room_temperature,'
    + 'climate.chambre_tom_room_temperature,climate.chambre_didier_room_temperature,'
    + 'climate.chambre_marie_room_temperature'));
const labels = list(eStr('CLIM_UNIT_LABELS',
    'Salon,Cuisine,Chambre Tom,Chambre Didier,Chambre Marie'));

msg.units = ids.map((id, i) => {
    const st = g[id];
    const raw = st?.state;
    const available = raw !== undefined && raw !== 'unavailable' && raw !== 'unknown';
    // Pas de coercition 'unavailable' → 'off' : repli sur le dernier état connu,
    // sinon chaque reboot HA déclencherait une fausse détection manuelle.
    const hvacMode = available ? raw : (getF('lastKnownHvac:' + id) || 'off');
    if (available) setF('lastKnownHvac:' + id, raw);

    const cur = parseFloat(st?.attributes?.current_temperature);
    const sp = parseFloat(st?.attributes?.temperature);
    const gr = groupOf[id] || null;
    return {
        id: id,
        label: labels[i] || id,
        priority: i + 1,
        group: gr ? gr.name : null,
        breakerOn: gr ? gr.breakerOn : true,
        available: available,
        hvacMode: hvacMode,
        on: hvacMode !== 'off',
        hvacAction: st?.attributes?.hvac_action || null,
        current: isNaN(cur) ? null : cur,
        tempAvailable: !isNaN(cur),
        setpoint: isNaN(sp) ? null : sp,
        modes: Array.isArray(st?.attributes?.hvac_modes) ? st.attributes.hvac_modes : []
    };
});

msg.unitCount = msg.units.length;
msg.anyTempAvailable = msg.units.some(u => u.tempAvailable);

// Suivi d'indisponibilité globale des températures (notification)
const nowMs = Date.now();
if (msg.anyTempAvailable) {
    setF('noTempSince', null);
    msg.noTempHours = 0;
} else {
    let ds = getF('noTempSince');
    if (!ds) { ds = nowMs; setF('noTempSince', ds); }
    msg.noTempHours = Math.round((nowMs - ds) / 360000) / 10;
}

// --- Cumulus : lecture du sensor du flow eau chaude (priorité absolue) ---
const cu = g[msg.cumulusSensor];
msg.cumulusFound = !!cu;
const ca = (cu && cu.attributes) || {};
msg.cumulus = {
    enabled: ca.enabled === true,
    desired: ca.desired || null,
    currentSwitch: ca.current_switch || null,
    power: parseFloat(ca.cumulus_power),
    waterTemp: parseFloat(ca.water_temp),
    reachFor: parseFloat(ca.reach_for),
    solarCoversTarget: ca.solar_covers_target === true,
    antiInjection: ca.anti_injection_useful === true || ca.anti_injection_active === true,
    legionellaPending: ca.legionella_critical_pending === true || ca.legionella_critical === true,
    thermostatTripped: ca.thermostat_tripped === true,
    manualHold: ca.manual_hold_active === true
};

return msg;

// === Détection du pilotage manuel, unité par unité ===
// Deux garde-fous, appliqués par unité pour que la chambre allumée à la main
// ne bloque pas le salon :
//  - PROPRIÉTÉ : une unité allumée hors du flow n'est jamais coupée par lui
//    (owned = false). Le confort demandé explicitement passe avant l'économie.
//  - PAUSE : tout changement de mode non commandé par le flow suspend
//    l'automatisation 45 min sur CETTE unité.
// États non exploitables (unavailable/unknown au reboot HA) ignorés par la
// détection, sinon chaque redémarrage vaudrait intervention manuelle.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const MANUAL_HOLD_MS = 45 * 60 * 1000;
const HA_LAG_GRACE_MS = 90 * 1000;   // tolérance de propagation d'état HA
const now = Date.now();

for (const u of msg.units) {
    const K = ':' + u.id;
    let expected = getF('expectedHvac' + K);
    if (expected == null && u.available) {
        expected = u.hvacMode;
        setF('expectedHvac' + K, expected);
    }
    const prevActionAt = getF('lastActionAt' + K) || 0;
    let holdUntil = getF('holdUntil' + K) || 0;
    let owned = getF('owned' + K) === true;

    if (u.available && expected != null
        && u.hvacMode !== expected
        && (now - prevActionAt) > HA_LAG_GRACE_MS) {
        holdUntil = now + MANUAL_HOLD_MS;
        setF('holdUntil' + K, holdUntil);
        expected = u.hvacMode;
        setF('expectedHvac' + K, expected);
        owned = false;                    // reprise en main par l'utilisateur
        setF('owned' + K, false);
        node.warn('Pilotage manuel détecté sur ' + u.label + ' → pause 45 min');
    }

    // Unité à l'arrêt : plus rien à revendiquer
    if (!u.on && owned) {
        owned = false;
        setF('owned' + K, false);
    }

    u.owned = owned;
    u.holdActive = now < holdUntil;
    u.holdUntil = holdUntil > now ? holdUntil : null;
    // En marche sans que le flow l'ait allumée : hors de son périmètre
    u.manualControl = u.on && !owned;
    // Temporisations compresseur, par unité
    const lastOnAt = getF('lastOnAt' + K) || 0;
    const lastOffAt = getF('lastOffAt' + K) || 0;
    u.minRunOk = (now - lastOnAt) >= msg.minRunMs;
    u.minOffOk = (now - lastOffAt) >= msg.minOffMs;
    u.minRunLeftMin = u.on ? Math.max(0, Math.ceil((msg.minRunMs - (now - lastOnAt)) / 60000)) : 0;
    u.minOffLeftMin = !u.on ? Math.max(0, Math.ceil((msg.minOffMs - (now - lastOffAt)) / 60000)) : 0;
}

msg.manualCount = msg.units.filter(u => u.manualControl).length;
msg.holdCount = msg.units.filter(u => u.holdActive).length;

return msg;

// === Priorité absolue à l'eau chaude ===
// Le surplus solaire finance d'abord le cumulus : la climatisation ne dispose
// que du reliquat. Deux situations à ne pas confondre, sous peine de compter
// deux fois la même énergie :
//   - cumulus DÉJÀ en chauffe : sa consommation est déjà retirée du surplus
//     mesuré au compteur réseau, aucune réservation supplémentaire ;
//   - cumulus à l'arrêt avec un besoin d'eau chaude non couvert : sa puissance
//     est RÉSERVÉE, la clim ne doit pas manger le surplus qui lui permettra de
//     démarrer (son hystérésis met 5 min à conclure).
// Sensor cumulus absent ou illisible : réservation par défaut, l'eau chaude ne
// perd jamais son surplus à cause d'une lecture manquante.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const CUMULUS_MIN_POWER_W = 100;
const now = Date.now();
const c = msg.cumulus || {};

// Seuil jusqu'auquel l'eau chaude garde la priorité sur le confort.
// 60 °C par défaut : température de référence anti-légionelle, donc ballon
// pleinement chargé et compteur de jours sans 60 °C remis à zéro avant tout
// usage du surplus pour le confort. Jamais en dessous de la cible du flow
// cumulus (reach_for monte à 62 °C quand un cycle légionelle est dû).
const reachFor = isNaN(c.reachFor) ? null : c.reachFor;
msg.hotWaterPriorityTemp = Math.max(msg.priorityTempSetting,
    reachFor != null ? reachFor : 0);

// --- Consommation récupérable de la clim ---
// « Récupérable » = ce que le flow rendrait au réseau en éteignant ce qu'il a
// allumé. Les unités lancées à la main n'en font pas partie : elles ne seront
// pas coupées, leur consommation reste à la charge de la maison.
// Mesure réelle par groupe de disjoncteur dès qu'elle est exploitable, c'est-à-
// dire quand TOUTES les unités en marche du groupe appartiennent au flow. Sinon
// un compteur de groupe agrège du récupérable et du non-récupérable sans
// permettre de les séparer : repli sur l'estimation CLIM_LOAD_W.
const ownedRunning = msg.units.filter(u => u.owned && u.on);
msg.ownedRunningCount = ownedRunning.length;
msg.ownedRunningLabels = ownedRunning.map(u => u.label);

let recoverable = 0;
let usedMeasure = false;
let usedEstimate = false;
const accounted = {};

for (const gr of msg.groups || []) {
    const inGroup = msg.units.filter(u => gr.units.indexOf(u.id) !== -1);
    for (const u of inGroup) accounted[u.id] = true;
    const running = inGroup.filter(u => u.on);
    const ownedInGroup = running.filter(u => u.owned);
    if (ownedInGroup.length === 0) continue;
    if (gr.power != null && running.length === ownedInGroup.length) {
        // Veille du disjoncteur retirée : elle subsiste après extinction.
        recoverable += Math.max(0, gr.power - msg.groupStandbyW);
        usedMeasure = true;
    } else {
        recoverable += ownedInGroup.length * msg.climLoadW;
        usedEstimate = true;
    }
}
// Unités hors de tout groupe déclaré : estimation
for (const u of ownedRunning) {
    if (!accounted[u.id]) { recoverable += msg.climLoadW; usedEstimate = true; }
}

msg.climDraw = Math.round(recoverable);
msg.climDrawSource = usedMeasure && usedEstimate ? 'mixte'
    : usedMeasure ? 'mesure' : usedEstimate ? 'estimation' : 'aucune';

// Consommation observée par unité en marche : sert à calibrer CLIM_LOAD_W sur
// les valeurs réelles de l'installation (les unités inverter modulent beaucoup).
const metered = (msg.groups || []).filter(gr => gr.power != null);
const measuredTotal = metered.reduce((sum, gr) => sum + Math.max(0, gr.power), 0);
const measuredNet = metered.reduce(
    (sum, gr) => sum + Math.max(0, gr.power - msg.groupStandbyW), 0);
const runningAll = msg.units.filter(u => u.on).length;
msg.climPowerTotalMeasured = metered.length > 0 ? Math.round(measuredTotal) : null;
msg.observedDrawPerUnit = (metered.length > 0 && runningAll > 0)
    ? Math.round(measuredNet / runningAll) : null;

const potentialSurplus = msg.surplus + msg.climDraw;
msg.potentialSurplus = Math.round(potentialSurplus);

// --- Réservation eau chaude ---
let reserve = 0;
let reason;
if (!msg.cumulusFound) {
    reserve = msg.cumulusLoadW;
    reason = 'sensor cumulus introuvable, réservation par sécurité';
} else if (!c.enabled) {
    reserve = 0;
    reason = 'automatisation cumulus désactivée';
} else if (!isNaN(c.power) && c.power >= CUMULUS_MIN_POWER_W) {
    reserve = 0;
    reason = 'cumulus en chauffe, consommation déjà déduite du surplus mesuré';
} else if (c.thermostatTripped && c.currentSwitch === 'on') {
    reserve = 0;
    reason = 'thermostat mécanique du cumulus ouvert, aucune consommation possible';
} else if (c.manualHold) {
    reserve = 0;
    reason = 'cumulus en pause manuelle';
} else if (c.desired === 'on') {
    reserve = msg.cumulusLoadW;
    reason = 'cumulus commandé ON, démarrage imminent';
} else if (c.antiInjection) {
    reserve = msg.cumulusLoadW;
    reason = 'anti-injection cumulus actif';
} else if (c.legionellaPending) {
    reserve = msg.cumulusLoadW;
    reason = 'cycle anti-légionelle en attente';
} else if (c.solarCoversTarget) {
    reserve = 0;
    reason = 'cible eau chaude couverte par le cumulus solaire amont';
} else if (isNaN(c.waterTemp)) {
    reserve = msg.cumulusLoadW;
    reason = 'température d\'eau illisible, réservation par sécurité';
} else if (c.waterTemp < msg.hotWaterPriorityTemp) {
    reserve = msg.cumulusLoadW;
    reason = 'eau à ' + c.waterTemp + '°C sous le seuil de priorité '
        + msg.hotWaterPriorityTemp + '°C';
} else {
    reserve = 0;
    reason = 'eau à ' + c.waterTemp + '°C, seuil de priorité '
        + msg.hotWaterPriorityTemp + '°C atteint, surplus libéré pour le confort';
}

msg.cumulusReserveW = Math.round(reserve);
msg.cumulusReserveReason = reason;
msg.hotWaterPriority = reserve > 0;

// --- Surplus réellement disponible pour la clim ---
msg.availableW = Math.round(potentialSurplus - reserve);
// Préemption : le surplus aurait suffi à au moins une unité, la réservation
// eau chaude le lui retire. Cas à afficher, distinct d'un manque de soleil.
msg.preemptedByHotWater = reserve > 0
    && potentialSurplus > msg.surplusTrigPerUnit
    && msg.availableW < msg.surplusTrigPerUnit;

// --- Estimation de l'énergie consommée par les cycles du flow (jour) ---
const lastSampleAt = getF('lastSampleAt');
let dtMs = lastSampleAt ? now - lastSampleAt : 0;
if (dtMs < 0 || dtMs > 10 * 60000) dtMs = 0;   // reprise après coupure : pas d'extrapolation
setF('lastSampleAt', now);

const dayKey = new Date(now).toISOString().slice(0, 10);
if (getF('energyDay') !== dayKey) {
    setF('energyDay', dayKey);
    setF('climWhToday', 0);
}
let wh = getF('climWhToday') || 0;
if (msg.climDraw > 0) wh += msg.climDraw * (dtMs / 3600000);
setF('climWhToday', wh);
msg.climKwhToday = Math.round(wh / 10) / 100;

return msg;

// === Besoin de confort et sens de fonctionnement, unité par unité ===
// Cibles communes à la maison (helpers HA), température propre à chaque pièce
// (attribut current_temperature de l'unité). Dépassement volontaire de la cible
// (CLIM_STORE_BAND) pour stocker l'énergie gratuite dans l'inertie du bâtiment,
// borné par CLIM_COOL_FLOOR / CLIM_HEAT_CEILING.
// Sens latché par unité pendant un cycle : pas de bascule froid ↔ chaud en
// cours de route.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const outdoor = msg.outdoorAvailable ? msg.outdoorTemp : null;
const seasonOff = msg.seasonMode === 'arret';

// Sens autorisé : forcé par le mode saison, ou déduit de l'extérieur en auto.
// Sonde extérieure absente : les deux sens restent possibles, l'écart intérieur
// tranche seul.
const canCool = !seasonOff && (msg.seasonMode === 'froid'
    || (msg.seasonMode === 'auto' && (outdoor == null || outdoor >= msg.outdoorCoolMin)));
const canHeat = !seasonOff && (msg.seasonMode === 'chaud'
    || (msg.seasonMode === 'auto' && (outdoor == null || outdoor <= msg.outdoorHeatMax)));
msg.canCool = canCool;
msg.canHeat = canHeat;

// Cibles de stockage (bornées par les garde-fous de confort)
const coolStore = Math.max(msg.targetCool - msg.storeBand, msg.coolFloor);
const heatStore = Math.min(msg.targetHeat + msg.storeBand, msg.heatCeiling);
msg.coolStore = Math.round(coolStore * 10) / 10;
msg.heatStore = Math.round(heatStore * 10) / 10;

for (const u of msg.units) {
    u.needMode = 'none';
    u.storeTarget = null;
    u.needReason = null;

    if (!u.available) {
        u.needReason = 'Unité injoignable';
        setF('modeLatch:' + u.id, null);
        continue;
    }
    if (!u.tempAvailable) {
        u.needReason = 'Température de la pièce illisible';
        setF('modeLatch:' + u.id, null);
        continue;
    }
    if (seasonOff) {
        u.needReason = 'Mode saison sur arrêt';
        setF('modeLatch:' + u.id, null);
        continue;
    }

    const t = u.current;
    const latch = getF('modeLatch:' + u.id);
    const running = u.on === true;

    let mode = 'none';
    if (canCool && t > msg.targetCool) {
        mode = 'cool';
    } else if (canHeat && t < msg.targetHeat) {
        mode = 'heat';
    } else if (running && latch === 'cool' && canCool && t > coolStore) {
        mode = 'cool';               // poursuite du cycle jusqu'à la cible de stockage
    } else if (running && latch === 'heat' && canHeat && t < heatStore) {
        mode = 'heat';
    }

    // Toutes les unités n'exposent pas 'cool'/'heat' (certaines n'ont que
    // 'heat_cool'). Liste vide (unité injoignable) : pas de blocage.
    u.modeSupported = mode === 'none' || u.modes.length === 0
        || u.modes.indexOf(mode) !== -1;

    if (mode !== 'none' && !u.modeSupported) {
        u.needMode = 'none';
        u.needReason = 'Mode ' + mode + ' non exposé par l\'unité ('
            + u.modes.join(', ') + ')';
        setF('modeLatch:' + u.id, null);
        continue;
    }

    if (mode === 'cool') {
        u.storeTarget = msg.coolStore;
        u.needReason = t > msg.targetCool
            ? t + '°C au-dessus de la cible froid ' + msg.targetCool + '°C'
            : 'Stockage de fraîcheur jusqu\'à ' + msg.coolStore + '°C';
    } else if (mode === 'heat') {
        u.storeTarget = msg.heatStore;
        u.needReason = t < msg.targetHeat
            ? t + '°C sous la cible chaud ' + msg.targetHeat + '°C'
            : 'Stockage de chaleur jusqu\'à ' + msg.heatStore + '°C';
    } else if (!canCool && !canHeat) {
        u.needReason = 'Saison neutre'
            + (outdoor != null ? ' (extérieur ' + outdoor + '°C)' : '');
    } else {
        u.needReason = 'Confort assuré (' + t + '°C)';
    }

    u.needMode = mode;
    setF('modeLatch:' + u.id, mode === 'none' ? null : mode);
}

msg.needCount = msg.units.filter(u => u.needMode !== 'none').length;

return msg;

// === Allocation du surplus par paliers, une unité à la fois ===
//
// Priorité de la décision, de haut en bas :
//   1. Automatisation désactivée            → aucune commande
//   2. Unité hors périmètre (allumée à la main, pause 45 min, injoignable)
//                                           → jamais touchée
//   3. Besoin de confort disparu            → libération immédiate, sans
//                                             attendre le surplus
//   4. Eau chaude prioritaire               → déjà retirée de availableW
//   5. Palier de surplus (±1 unité)         → hystérésis CLIM_HYST_MIN
//   6. Anti court-cycle, par unité          → min-run / min-off
//
// Un palier = CLIM_LOAD_W de surplus disponible. availableW réintègre déjà la
// consommation des unités pilotées : le nombre finançable se lit donc
// directement, sans raisonner en différentiel.
// Une seule unité ajoutée ou retirée par palier confirmé : montée progressive
// (5 min par unité), et délestage du moins prioritaire en premier.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const HARD_STOP_MS = 2 * 60 * 1000;
const now = Date.now();
const perUnit = msg.surplusTrigPerUnit;

// --- Garde-fou : import réseau réel ---
// ATTENTION : availableW > 0 ne signifie pas qu'on n'importe pas. C'est le
// surplus qu'on AURAIT toutes unités du flow arrêtées ; avec 3 unités et
// 800 W disponibles, on tire 1600 W du réseau tout en affichant availableW
// positif. Le seul juge de l'import est le compteur réseau.
// C'est aussi ce qui rend la priorité eau chaude effective en plein cycle :
// le cumulus qui redémarre fait basculer le compteur en import.
let importSince = getF('gridImportSince');
msg.gridImporting = msg.surplus < 0;
if (msg.gridImporting && msg.ownedRunningCount > 0) {
    if (!importSince) { importSince = now; setF('gridImportSince', now); }
    msg.hardStop = (now - importSince) > HARD_STOP_MS;
} else {
    setF('gridImportSince', null);
    msg.hardStop = false;
}

// --- 1. Automatisation désactivée : rien n'est commandé ---
if (!msg.enabled) {
    for (const u of msg.units) { u.desired = 'skip'; u.desiredReason = 'automatisation désactivée'; }
    setF('pendingCount', null);
    setF('pendingSince', null);
    msg.targetCount = 0;
    msg.tierCandidate = 0;
    msg.tierPendingMin = 0;
    msg.state = 'Désactivé';
    msg.reason = 'Automatisation désactivée, aucune commande envoyée';
    return msg;
}

// --- 2. Unités hors périmètre ---
for (const u of msg.units) {
    u.desired = null;
    if (u.manualControl) {
        u.desired = 'skip';
        u.desiredReason = 'allumée hors automatisation, non modifiée';
    } else if (u.breakerOn === false) {
        // Disjoncteur ouvert : l'unité est de toute façon injoignable, mais la
        // cause exacte vaut mieux qu'un « injoignable » générique.
        u.desired = 'skip';
        u.desiredReason = 'disjoncteur ' + (u.group || '?') + ' coupé';
    } else if (!u.available) {
        u.desired = 'skip';
        u.desiredReason = 'injoignable, aucune commande';
    } else if (u.holdActive && !u.on) {
        u.desired = 'skip';
        u.desiredReason = 'pause après intervention manuelle';
    }
}

// --- 3. Libération immédiate des unités sans besoin ---
// Confort atteint ou sonde muette : pas une question de surplus, aucun délai.
const keep = [];
for (const u of msg.units) {
    if (u.desired || !u.owned || !u.on) continue;
    if (u.needMode === 'none') {
        u.desired = 'off';
        u.desiredReason = u.needReason || 'plus de besoin';
    } else {
        keep.push(u);
    }
}

// --- 5. Palier de surplus ---
const n = keep.length;
const eligible = msg.units.filter(u =>
    !u.desired && u.needMode !== 'none' && u.available
    && u.modeSupported && !u.manualControl && !u.holdActive);

let candidate = n;
if (msg.availableW > (n + 1) * perUnit) candidate = n + 1;
else if (n > 0 && msg.availableW < n * perUnit * msg.stopRatio) candidate = n - 1;

// Bornage : jamais plus d'unités que d'éligibles, ni que CLIM_MAX_UNITS
candidate = Math.max(0, Math.min(candidate, eligible.length, msg.maxUnits));

let committed = n;
let pendingLeftMs = 0;
if (candidate !== n) {
    const pend = getF('pendingCount');
    const pendSince = getF('pendingSince') || 0;
    if (pend === candidate) {
        if (now - pendSince > msg.hystMs) {
            committed = candidate;
            setF('pendingCount', null);
            setF('pendingSince', null);
        } else {
            pendingLeftMs = msg.hystMs - (now - pendSince);
        }
    } else {
        setF('pendingCount', candidate);
        setF('pendingSince', now);
        pendingLeftMs = msg.hystMs;
    }
} else {
    setF('pendingCount', null);
    setF('pendingSince', null);
}

// --- Délestage latché ---
// Une réduction confirmée mais bloquée par un min-run ne doit PAS relancer
// l'hystérésis au tick suivant : sans latch, la cible retombe à n, se reconfirme
// 5 min plus tard, rebloque, et le délestage n'arrive jamais franchement.
const held = getF('shedTarget');
if (held != null && held < n) {
    if (msg.availableW < n * perUnit * msg.stopRatio) {
        committed = Math.min(committed, held);
        pendingLeftMs = 0;
    } else {
        setF('shedTarget', null);          // budget revenu, plus rien à délester
    }
}

// Import réseau confirmé : une unité délestée par tick jusqu'à l'arrêt de
// l'import, sans attendre l'hystérésis (chaque minute de plus est payée).
if (msg.hardStop) committed = Math.max(0, n - 1);

const targetCount = Math.max(0, committed);
msg.tierCandidate = candidate;
msg.targetCount = targetCount;
msg.tierPendingMin = Math.ceil(pendingLeftMs / 60000);
msg.eligibleCount = eligible.length;

// --- 6. Application, anti court-cycle par unité ---
msg.shedDeferred = false;
if (targetCount < n) {
    // Ordre STRICT de priorité, du moins prioritaire vers le plus prioritaire.
    // Une unité bloquée par son min-run arrête le parcours : hors de question
    // de délester une pièce plus prioritaire simplement parce qu'elle est, elle,
    // délestable (les unités ne démarrent pas en même temps, leurs min-run
    // n'expirent donc pas en même temps). On attend, ou l'import réseau tranche.
    const victims = keep.slice().sort((a, b) => b.priority - a.priority);
    const toShed = n - targetCount;
    let shed = 0;
    for (const u of victims) {
        if (shed >= toShed) break;
        if (!msg.hardStop && !u.minRunOk) {
            msg.shedBlockedBy = u.label;
            msg.shedBlockedMin = u.minRunLeftMin;
            break;
        }
        u.desired = 'off';
        u.desiredReason = msg.hardStop
            ? 'import réseau confirmé, délestage immédiat'
            : (msg.preemptedByHotWater
                ? 'surplus repris par l\'eau chaude'
                : 'surplus insuffisant pour ' + n + ' unité(s)');
        shed++;
    }
    msg.shedDeferred = shed < toShed;
} else if (targetCount > n) {
    // Démarrage du plus prioritaire d'abord
    const startable = eligible
        .filter(u => !u.on && u.minOffOk)
        .sort((a, b) => a.priority - b.priority);
    const toStart = targetCount - n;
    for (let i = 0; i < toStart && i < startable.length; i++) {
        startable[i].desired = 'on';
        startable[i].desiredReason = 'surplus libre ' + msg.availableW + ' W après eau chaude';
    }
}

// Unités conservées et reliquat
for (const u of keep) {
    if (!u.desired) {
        u.desired = 'on';
        u.desiredReason = u.needReason;
    }
}
for (const u of msg.units) {
    if (!u.desired) {
        u.desired = 'off';
        if (!u.desiredReason) {
            u.desiredReason = u.needMode === 'none'
                ? u.needReason
                : (u.on ? 'en attente' : 'en attente de surplus');
        }
    }
}

// Latch : conservé tant que le délestage n'a pas pu être appliqué
if (msg.shedDeferred) setF('shedTarget', targetCount);
else setF('shedTarget', null);

// --- Synthèse pour le sensor ---
const onUnits = msg.units.filter(u => u.desired === 'on');
const modes = onUnits.map(u => u.needMode);
msg.activeLabels = onUnits.map(u => u.label);
msg.activeCount = onUnits.length;

if (msg.shedDeferred && msg.activeCount > 0) {
    msg.state = 'Arrêt différé (anti court-cycle)';
    msg.reason = 'Surplus insuffisant pour ' + msg.activeCount + ' unité(s), arrêt de '
        + (msg.shedBlockedBy || '?') + ' dans ' + (msg.shedBlockedMin || 0)
        + ' min (protection compresseur)';
} else if (msg.activeCount > 0) {
    const cooling = modes.indexOf('cool') !== -1;
    const heating = modes.indexOf('heat') !== -1;
    msg.state = (cooling && heating) ? 'Confort gratuit'
        : cooling ? 'Rafraîchissement gratuit' : 'Chauffage gratuit';
    msg.reason = msg.activeLabels.join(', ') + ' · surplus libre ' + msg.availableW
        + ' W (' + msg.activeCount + ' × ' + msg.climLoadW + ' W)';
} else if (msg.manualCount > 0 && msg.needCount === 0) {
    msg.state = 'Pilotage manuel';
    msg.reason = msg.units.filter(u => u.manualControl).map(u => u.label).join(', ')
        + ' allumée(s) hors automatisation, non modifiée(s)';
} else if (msg.needCount === 0) {
    msg.state = msg.seasonMode === 'arret' ? 'Mode saison arrêté'
        : (!msg.canCool && !msg.canHeat) ? 'Hors saison' : 'Confort atteint';
    msg.reason = 'Aucune pièce en demande'
        + (msg.outdoorAvailable ? ' (extérieur ' + msg.outdoorTemp + '°C)' : '');
} else if (msg.preemptedByHotWater) {
    msg.state = 'Veille (eau chaude prioritaire)';
    msg.reason = 'Surplus de ' + msg.potentialSurplus + ' W réservé au cumulus : '
        + msg.cumulusReserveReason;
} else if (msg.tierPendingMin > 0) {
    msg.state = 'Démarrage différé';
    msg.reason = 'Surplus en cours de confirmation, ' + msg.tierPendingMin
        + ' min avant ' + msg.tierCandidate + ' unité(s)';
} else {
    msg.state = 'Veille (surplus insuffisant)';
    msg.reason = 'Surplus libre ' + msg.availableW + ' W, seuil ' + perUnit
        + ' W par unité';
}

return msg;

// === Émission des commandes, une par unité à changer ===
// Sortie 1 : un message par unité à commander, chacun portant sa propre cible
// (payload.target.entity_id) — les nœuds de service ne fixent aucune entité en
// dur, l'unité vient du message.
//   service = 'start'  → set_hvac_mode puis set_temperature (chaînés)
//   service = 'adjust' → idem, réalignement mode/consigne d'un cycle en cours
//   service = 'stop'   → turn_off
// Sortie 2 : le message de synthèse, vers le sensor et les alertes.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const SETPOINT_TOL = 0.2;
const now = Date.now();
const cmds = [];

for (const u of msg.units) {
    u.action = 'none';
    const K = ':' + u.id;

    if (u.desired === 'skip') continue;

    if (u.desired === 'on' && !u.on) {
        u.action = 'start';
        setF('lastOnAt' + K, now);
        setF('lastActionAt' + K, now);
        setF('expectedHvac' + K, u.needMode);
        setF('owned' + K, true);
        u.owned = true;
    } else if (u.desired === 'off' && u.on) {
        // Garde-fou : le flow n'éteint que ce qu'il a allumé.
        if (!u.owned) continue;
        u.action = 'stop';
        setF('lastOffAt' + K, now);
        setF('lastActionAt' + K, now);
        setF('expectedHvac' + K, 'off');
        setF('owned' + K, false);
        u.owned = false;
    } else if (u.desired === 'on' && u.on && u.owned) {
        // Réalignement si le mode ou la consigne a dérivé (bascule froid/chaud,
        // cible modifiée par l'utilisateur).
        const modeDrift = u.hvacMode !== u.needMode;
        const spDrift = u.storeTarget != null
            && (u.setpoint == null || Math.abs(u.setpoint - u.storeTarget) > SETPOINT_TOL);
        if (modeDrift || spDrift) {
            u.action = 'adjust';
            setF('lastActionAt' + K, now);
            setF('expectedHvac' + K, u.needMode);
            u.desiredReason = (u.desiredReason || '') + ' · réalignement '
                + (modeDrift ? 'mode ' + u.needMode : 'consigne ' + u.storeTarget + '°C');
        }
    }

    if (u.action === 'none') continue;

    setF('lastActionReason' + K, u.desiredReason);
    cmds.push({
        service: u.action === 'stop' ? 'stop' : 'start',
        unit: u.label,
        unitId: u.id,
        hvacModeCmd: u.needMode,
        tempCmd: u.storeTarget,
        reason: u.label + ' → ' + (u.action === 'stop' ? 'arrêt' : u.needMode)
            + ' : ' + u.desiredReason,
        payload: { target: { entity_id: u.id } }
    });
}

msg.actions = msg.units.filter(u => u.action !== 'none')
    .map(u => ({ unit: u.label, action: u.action }));
msg.actionCount = msg.actions.length;
msg.now = now;

// Historique global (affichage)
if (msg.actionCount > 0) {
    setF('lastActionAt', now);
    setF('lastActionSummary', msg.actions
        .map(a => a.unit + ' ' + a.action).join(', '));
    setF('lastActionReason', msg.reason);
}
msg.lastActionAt = getF('lastActionAt');
msg.lastActionSummary = getF('lastActionSummary');
msg.lastActionReason = getF('lastActionReason');

return [cmds.length ? cmds : null, msg];

// === Alertes HA (persistent_notification) ===
// Une notification par épisode, anti-spam par contexte persistant.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const out = [];
const now = Date.now();
const DAY_MS = 24 * 3600 * 1000;

// 1. Plus aucune température de pièce depuis ≥ 2 h
if ((msg.noTempHours || 0) >= 2) {
    if (!getF('notifNoTemp')) {
        setF('notifNoTemp', true);
        out.push({ payload: {
            notification_id: 'clim_sondes_hs',
            title: 'Clim : plus aucune température de pièce',
            message: 'Aucune unité ne remonte de current_temperature depuis '
                + msg.noTempHours + ' h. Confort gratuit suspendu (pas de '
                + 'pilotage à l\'aveugle).'
        }});
    }
} else if (msg.anyTempAvailable) {
    setF('notifNoTemp', false);
}

// 2. Sensor cumulus introuvable : la priorité eau chaude tourne en aveugle,
//    avec réservation permanente du surplus.
if (msg.cumulusFound === false) {
    const last = getF('notifNoCumulusAt') || 0;
    if (now - last > DAY_MS) {
        setF('notifNoCumulusAt', now);
        out.push({ payload: {
            notification_id: 'clim_cumulus_absent',
            title: 'Clim : sensor cumulus introuvable',
            message: msg.cumulusSensor + ' absent. ' + msg.cumulusLoadW + ' W réservés '
                + 'en permanence à l\'eau chaude par sécurité. Variable '
                + 'CUMULUS_SENSOR à vérifier.'
        }});
    }
}

// 3. Unités injoignables depuis ≥ 1 h
const down = (msg.units || []).filter(u => u.available === false);
if (down.length > 0) {
    let since = getF('unitsDownSince');
    if (!since) { since = now; setF('unitsDownSince', now); }
    if (now - since > 3600 * 1000) {
        const key = down.map(u => u.id).sort().join(',');
        if (getF('notifUnitsDownKey') !== key) {
            setF('notifUnitsDownKey', key);
            out.push({ payload: {
                notification_id: 'clim_unites_injoignables',
                title: 'Clim : unité(s) injoignable(s)',
                message: down.map(u => u.label).join(', ')
                    + ' indisponible(s) depuis plus d\'une heure, aucune commande envoyée.'
            }});
        }
    }
} else {
    setF('unitsDownSince', null);
    setF('notifUnitsDownKey', null);
}

// 4. Unité en demande mais mode absent de ses hvac_modes (erreur de config)
const unsupported = (msg.units || []).filter(u => u.modeSupported === false);
if (unsupported.length > 0) {
    const key = unsupported.map(u => u.id).sort().join(',');
    if (getF('notifUnsupportedKey') !== key) {
        setF('notifUnsupportedKey', key);
        out.push({ payload: {
            notification_id: 'clim_mode_non_supporte',
            title: 'Clim : mode non exposé par une unité',
            message: unsupported.map(u => u.label + ' (' + u.modes.join(', ') + ')').join(' · ')
                + '. Aucune commande envoyée à ces unités.'
        }});
    }
} else {
    setF('notifUnsupportedKey', null);
}

// 5. Disjoncteur ouvert alors qu'il resterait du surplus à exploiter.
//    Le besoin de confort des pièces concernées n'est PAS testé : disjoncteur
//    coupé, leurs entités sont injoignables, donc sans besoin exprimable — le
//    tester ne déclencherait jamais l'alerte. Le signal utile est le surplus
//    perdu. (Pas de doublon avec l'automatisation HA « alimentation disjoncteur
//    coupée » : ici l'angle est la perte de capacité de confort gratuit.)
const cutGroups = (msg.groups || []).filter(gr => gr.breakerKnown && !gr.breakerOn);
if (cutGroups.length > 0 && msg.enabled
    && msg.availableW > msg.surplusTrigPerUnit) {
    const key = cutGroups.map(gr => gr.name).sort().join(',');
    if (getF('notifBreakerKey') !== key) {
        setF('notifBreakerKey', key);
        out.push({ payload: {
            notification_id: 'clim_disjoncteur_coupe',
            title: 'Clim : disjoncteur coupé, confort gratuit indisponible',
            message: 'Disjoncteur ' + key + ' hors tension alors que '
                + msg.availableW + ' W de surplus restent disponibles. Pièces de ce '
                + 'groupe hors du confort gratuit.'
        }});
    }
} else {
    setF('notifBreakerKey', null);
}

if (out.length === 0) return null;
return [out];

// === Gestion des erreurs du flow (nœud catch) ===

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const src = (msg.error && msg.error.source) || {};
const SERVICE_NODES = ["c0f1000000000018", "c0f1000000000019", "c0f100000000001a"]; // set_hvac_mode / set_temperature / turn_off

// Commande échouée : l'historique optimiste est faux pour CETTE unité → purge,
// sinon l'anti court-cycle et la détection de pilotage manuel dérivent. L'unité
// visée est portée par le message d'origine (payload.target.entity_id).
const failedId = msg.payload?.target?.entity_id || msg.unitId;
if (SERVICE_NODES.indexOf(src.id) !== -1 && failedId) {
    const K = ':' + failedId;
    setF('lastActionAt' + K, 0);
    setF('expectedHvac' + K, null);
    setF('owned' + K, false);
    node.warn('Commande clim échouée sur ' + failedId + ', état du flow purgé');
}

// Anti-spam : 1 notification max / 15 min
const now = Date.now();
const last = getF('lastErrorNotifAt') || 0;
if (now - last < 15 * 60 * 1000) return null;
setF('lastErrorNotifAt', now);

msg.payload = {
    notification_id: 'clim_flow_error',
    title: 'Clim : erreur dans le flow',
    message: (src.name || src.id || '?') + ' : '
        + (msg.error && msg.error.message ? msg.error.message : 'erreur inconnue')
        + (failedId ? ' (' + failedId + ')' : '')
};
return msg;
